import{_ as e,I as o,o as s,c as i,a7 as r,b as l,w as a,a as d,J as g,a8 as h,ab as E}from"./chunks/framework.CfVpnaIe.js";const D=JSON.parse('{"title":"设备","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"device.md","filePath":"device.md"}'),p={name:"device.md"};function c(A,t,b,B,u,_){const n=o("Mermaid");return s(),i("div",null,[t[1]||(t[1]=r('<h1 id="设备" tabindex="-1">设备 <a class="header-anchor" href="#设备" aria-label="Permalink to “设备”">​</a></h1><p>相关文档：<a href="/music-free-site/music.html">音乐管理</a> · <a href="/music-free-site/playlist.html">歌单</a> · <a href="/music-free-site/user.html">用户</a></p><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><p><strong>设备模块</strong>让 MusicFree 通过 <strong>DLNA / UPnP AV</strong> 协议将音乐推送到局域网内的音频设备（智能音箱、电视、功放、DLNA 播放器等）上播放，让手机 / 电脑成为遥控器，让客厅的音响出声。</p><p><img src="'+E+'" alt=""></p><blockquote><p>该功能自 <strong>V1.2.2</strong> 起提供，详见 <a href="/music-free-site/changelog.html">发布日志</a>。</p></blockquote>',6)),(s(),l(h,null,{default:a(()=>[g(n,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20lan%20%5B%E5%B1%80%E5%9F%9F%E7%BD%91%5D%0A%20%20%20%20DEV1%5BDLNA%20%E9%9F%B3%E7%AE%B1%5D%0A%20%20%20%20DEV2%5B%E7%94%B5%E8%A7%86%20%2F%20%E5%8A%9F%E6%94%BE%5D%0A%20%20%20%20DEV3%5B%E5%85%B6%E4%BB%96%20DLNA%20%E6%B8%B2%E6%9F%93%E5%99%A8%5D%0A%20%20end%0A%20%20subgraph%20admin%20%5B%E7%AE%A1%E7%90%86%E5%91%98%5D%0A%20%20%20%20ADMIN%5B%E8%AE%BE%E5%A4%87%E7%AE%A1%E7%90%86%20%2Fadmin%2Fdevices%5D%0A%20%20end%0A%20%20subgraph%20user%20%5B%E6%99%AE%E9%80%9A%E7%94%A8%E6%88%B7%5D%0A%20%20%20%20USER%5B%E6%92%AD%E6%94%BE%E5%99%A8%20%E2%86%92%20%E6%92%AD%E6%94%BE%E5%88%B0%E8%AE%BE%E5%A4%87%5D%0A%20%20end%0A%20%20ADMIN%20--%3E%7CSSDP%20%E5%8F%91%E7%8E%B0%E5%B9%B6%E6%B7%BB%E5%8A%A0%E8%AE%BE%E5%A4%87%7C%20DEV1%0A%20%20ADMIN%20--%3E%7CSSDP%20%E5%8F%91%E7%8E%B0%E5%B9%B6%E6%B7%BB%E5%8A%A0%E8%AE%BE%E5%A4%87%7C%20DEV2%0A%20%20ADMIN%20--%3E%7CSSDP%20%E5%8F%91%E7%8E%B0%E5%B9%B6%E6%B7%BB%E5%8A%A0%E8%AE%BE%E5%A4%87%7C%20DEV3%0A%20%20ADMIN%20--%3E%7C%E6%8E%88%E6%9D%83%E7%BB%99%E6%8C%87%E5%AE%9A%E7%94%A8%E6%88%B7%7C%20USER%0A%20%20USER%20--%3E%7CUPnP%20%E6%8E%A7%E5%88%B6%E5%B7%B2%E6%8E%88%E6%9D%83%E8%AE%BE%E5%A4%87%7C%20DEV1%0A%20%20USER%20--%3E%7CUPnP%20%E6%8E%A7%E5%88%B6%E5%B7%B2%E6%8E%88%E6%9D%83%E8%AE%BE%E5%A4%87%7C%20DEV2%0A%20%20USER%20--%3E%7CUPnP%20%E6%8E%A7%E5%88%B6%E5%B7%B2%E6%8E%88%E6%9D%83%E8%AE%BE%E5%A4%87%7C%20DEV3%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r(`<p><strong>权限模型</strong>：</p><ul><li><strong>设备只能由管理员添加</strong>：管理员通过 SSDP 发现局域网内的 DLNA 设备并登记入库。</li><li><strong>管理员按需授权</strong>：添加后可把设备 <strong>授权给某个普通用户</strong>。</li><li><strong>普通用户只可用被授权的设备</strong>：播放时仅能选择管理员已授权给 <strong>本人</strong> 的设备。</li></ul><p><strong>能力边界</strong>：</p><ul><li>设备管理仅通过 <strong>Web UI</strong> 提供，<strong>不在</strong> OpenSubsonic / Navidrome 协议中暴露。</li><li>只能推送到 <strong>局域网内</strong>、支持 <strong>DLNA / UPnP AV</strong>（MediaRenderer）的设备；无法控制第三方云端音箱（需厂商 App / 平台开放能力）。</li></ul><h2 id="_2-访问与权限" tabindex="-1">2. 访问与权限 <a class="header-anchor" href="#_2-访问与权限" aria-label="Permalink to “2. 访问与权限”">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>入口</th><th>路径</th><th>能力</th></tr></thead><tbody><tr><td>管理员</td><td>管理后台侧栏 → <strong>设备管理</strong></td><td><code>/admin/devices</code></td><td>发现 / 添加设备、查看在线状态、<strong>授权给用户</strong>、播放控制</td></tr><tr><td>普通用户</td><td>播放器 → <strong>播放到设备</strong></td><td><code>/devices</code></td><td>仅能选择<strong>被授权给本人</strong>的设备进行播放与简单控制</td></tr></tbody></table><ul><li><strong>管理员</strong>：须管理员权限（<code>requiresAdmin</code>）；负责设备的添加、管理与授权。</li><li><strong>普通用户</strong>：须登录；只能查看、使用管理员 <strong>授权给本人</strong> 的设备，看不到其他设备。</li></ul><h2 id="_3-设备添加-管理员" tabindex="-1">3. 设备添加（管理员） <a class="header-anchor" href="#_3-设备添加-管理员" aria-label="Permalink to “3. 设备添加（管理员）”">​</a></h2><h3 id="_3-1-设备发现" tabindex="-1">3.1 设备发现 <a class="header-anchor" href="#_3-1-设备发现" aria-label="Permalink to “3.1 设备发现”">​</a></h3><p>服务端通过 <strong>SSDP（Simple Service Discovery Protocol）</strong> 在局域网内组播发现 DLNA 设备：</p><ul><li>进入「设备管理」时自动发起 <strong>发现</strong>，并持续监听设备的 <strong>上线 / 下线</strong> 通知。</li><li>发现结果展示设备的 <strong>名称</strong>、<strong>型号</strong> 与 <strong>服务能力</strong>（如支持的传输协议）。</li><li>未添加的设备仅作为 <strong>候选</strong> 展示，<strong>不会</strong>自动入库，须管理员手动 <strong>添加</strong>。</li></ul><blockquote><p><strong>提示</strong>：若设备未出现在列表，请确认设备与 MusicFree 处于 <strong>同一局域网 / 子网</strong>，且设备已开机并启用 DLNA / 投屏功能；部分设备需要先在自身设置中开启「DLNA 渲染」或「局域网共享 / 投屏」。</p></blockquote><h3 id="_3-2-添加设备" tabindex="-1">3.2 添加设备 <a class="header-anchor" href="#_3-2-添加设备" aria-label="Permalink to “3.2 添加设备”">​</a></h3><p>管理员在候选设备列表中点击 <strong>添加</strong>，将该设备登记入库：</p><ul><li>添加后可设置设备 <strong>名称</strong>（便于识别）等基本信息。</li><li>已添加的设备进入 <strong>设备列表</strong>，可由管理员统一管理。</li></ul><h2 id="_4-设备管理-admin-devices" tabindex="-1">4. 设备管理（/admin/devices） <a class="header-anchor" href="#_4-设备管理-admin-devices" aria-label="Permalink to “4. 设备管理（/admin/devices）”">​</a></h2><p>「设备管理」页面供管理员集中管理局域网内已添加的 DLNA 设备：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>设备列表</strong></td><td>展示已添加设备的名称、类型、状态与授权对象</td></tr><tr><td><strong>刷新发现</strong></td><td>手动触发一次 SSDP 发现，拉取最新候选设备</td></tr><tr><td><strong>添加设备</strong></td><td>将发现的候选设备登记入库</td></tr><tr><td><strong>授权给用户</strong></td><td>选择某个普通用户，将该设备授权给 TA 使用</td></tr><tr><td><strong>取消授权</strong></td><td>收回设备授权，对应普通用户将无法再使用该设备</td></tr><tr><td><strong>移除设备</strong></td><td>从设备列表移除（删除登记），所有授权一并失效</td></tr><tr><td><strong>播放控制</strong></td><td>对设备执行 <strong>播放 / 暂停 / 停止 / 上一曲 / 下一曲</strong></td></tr></tbody></table><h3 id="_4-1-设备授权" tabindex="-1">4.1 设备授权 <a class="header-anchor" href="#_4-1-设备授权" aria-label="Permalink to “4.1 设备授权”">​</a></h3><ul><li>一台设备可授权给 <strong>一个或多个普通用户</strong>，也可同时保留给管理员自己使用。</li><li>授权不限制设备在线状态：设备离线时授权仍保留，上线后普通用户即可恢复使用。</li><li><strong>取消授权 / 移除设备</strong> 后，该用户 <strong>立即失去</strong> 对该设备的使用能力。</li></ul><h2 id="_5-播放到设备-普通用户" tabindex="-1">5. 播放到设备（普通用户） <a class="header-anchor" href="#_5-播放到设备-普通用户" aria-label="Permalink to “5. 播放到设备（普通用户）”">​</a></h2><p>普通用户在 MusicFree 中可将以下内容推送到 <strong>已被授权给本人</strong> 的设备：</p><table tabindex="0"><thead><tr><th>内容</th><th>操作说明</th></tr></thead><tbody><tr><td><strong>单曲</strong></td><td>歌曲列表 / 详情页选择 <strong>播放到设备</strong>，选择已授权设备播放</td></tr><tr><td><strong>专辑</strong></td><td>专辑详情选择 <strong>播放到设备</strong>，按专辑曲目顺序连续播放</td></tr><tr><td><strong>歌单</strong></td><td>歌单详情选择 <strong>播放到设备</strong>，按歌单曲目顺序连续播放</td></tr><tr><td><strong>当前播放</strong></td><td>播放器内 <strong>切换播放设备</strong>，将正在播放的内容转移到目标设备</td></tr></tbody></table><p>推送后：</p><ul><li>设备开始播放由 MusicFree 提供的 <strong>音频流</strong>（由 MusicFree 服务端对曲目进行流式转码 / 直出）。</li><li>普通用户仅可对 <strong>授权给本人</strong> 的设备执行播放控制；未授权设备不出现在其列表中。</li><li>播放进度、曲目变化由服务端与设备之间通过 UPnP 状态同步，页面可查看当前设备播放状态。</li></ul><blockquote><p><strong>注意</strong>：推送到 DLNA 设备后，声音由 <strong>目标设备</strong> 播出，浏览器 / 设备默认不再发声；如需切回本地播放，请断开或选择 <strong>本地播放</strong>。</p></blockquote><h2 id="_6-典型工作流" tabindex="-1">6. 典型工作流 <a class="header-anchor" href="#_6-典型工作流" aria-label="Permalink to “6. 典型工作流”">​</a></h2><h3 id="_6-1-管理员添加设备并授权" tabindex="-1">6.1 管理员添加设备并授权 <a class="header-anchor" href="#_6-1-管理员添加设备并授权" aria-label="Permalink to “6.1 管理员添加设备并授权”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ 管理后台 → 设备管理 → 刷新发现</span></span>
<span class="line"><span>    → 选择候选设备 → 添加</span></span>
<span class="line"><span>    → 设备列表中对该设备「授权给用户」→ 选择目标普通用户</span></span>
<span class="line"><span>    → 完成，该用户即可使用该设备</span></span></code></pre></div><h3 id="_6-2-普通用户推送到音箱播放一首歌" tabindex="-1">6.2 普通用户推送到音箱播放一首歌 <a class="header-anchor" href="#_6-2-普通用户推送到音箱播放一首歌" aria-label="Permalink to “6.2 普通用户推送到音箱播放一首歌”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>确认音箱已开机且与 MusicFree 同一局域网</span></span>
<span class="line"><span>    → 歌曲详情 / 列表 →「播放到设备」</span></span>
<span class="line"><span>    → 选择已授权的目标音箱 → 音箱开始播放</span></span>
<span class="line"><span>    → 播放器内可暂停 / 下一曲 / 停止</span></span></code></pre></div><h3 id="_6-3-管理员收回设备权限" tabindex="-1">6.3 管理员收回设备权限 <a class="header-anchor" href="#_6-3-管理员收回设备权限" aria-label="Permalink to “6.3 管理员收回设备权限”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备管理 → 选择设备 →「取消授权」或「移除设备」</span></span>
<span class="line"><span>    → 对应普通用户立即无法再使用该设备</span></span></code></pre></div><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to “7. 常见问题”">​</a></h2><p><strong>Q：普通用户为什么看不到设备列表里的设备？</strong><br> A：设备需要管理员 <strong>添加并授权</strong> 给该用户后才能使用。请联系管理员在 <strong>设备管理</strong> 中完成授权。</p><p><strong>Q：普通用户能自己添加局域网设备吗？</strong><br> A：不能。设备添加仅限管理员，普通用户只能使用被授权的设备。</p><p><strong>Q：为什么设备管理页面找不到我的音响？</strong><br> A：请确认设备与 MusicFree 处于<strong>同一局域网 / 子网</strong>、已开机且开启了 DLNA / 投屏 / 局域网共享功能；部分设备需在自身设置中手动开启。也可点击 <strong>刷新发现</strong> 重新扫描。</p><p><strong>Q：取消授权后设备还在吗？</strong><br> A：在。取消授权只收回某个用户的使用权，设备仍保留在管理员设备列表中；需要彻底移除请使用 <strong>移除设备</strong>。</p><p><strong>Q：DLNA 设备能跨局域网 / 远程推送吗？</strong><br> A：不能。DLNA 基于局域网组播发现与控制，仅支持同一局域网内的设备。</p>`,39))])}const k=e(p,[["render",c]]);export{D as __pageData,k as default};
